        "message": "பாடசாலை போசாக்கு நிகழ்ச்சித் திட்டத்தின் கீழ் தெரிவு செய்யப்பட்ட பயனாளிகளை 2026.10.20 அன்று நடைபெறும் விவசாயச் செயற்றிட்டப் பயிற்சி நெறியில் பங்குபற்றச் செய்யுமாறு கோரப்பட்டுள்ளது.",
