        "senderRole": "Mail Officer",
        "message": "அரசு உத்தியோகத்தர்களின் முற்பணம் 'பி' கணக்கு தொடர்பான மாதாந்த வரவு பற்று விபரங்களை CIGAS ஊடாக தயாரித்து மாவட்டச் செயலகத்திற்கு அனுப்பிவைக்கக் கோரும் கடிதம்.",
